for i in [299,298,297,294,289,283]:
 for mode in ['observed','TT170','interior']:
  x=X[i].copy()
  if mode!='observed': x[9]=170
  if mode=='interior': x=np.clip(x,lo/.95,hi/1.05)
  pts=x*(1+shifts); pred=np.array([fitted[n].predict(pts) for n in models_used]); mean=pred.mean(0); worst=mean.argmin(); print(i,mode,'ensemble',round(mean[0],1),round(mean.min(),1),'worst',('nominal' if worst==0 else cols[(worst-1)%25]+('-5%' if worst<=25 else '+5%')),'permodel',[(n,round(p[0],1),round(p.min(),1)) for n,p in zip(models_used,pred)]); 
print('IMPORTANCE'); print(pd.DataFrame({n:fitted[n].feature_importances_ for n in ['cat4','extra','rf','gbr']},index=cols).sort_values('rf',ascending=False).round(4).to_string())"

